EVENTS = [
    dict(id="founding-corduba", title="Marcellus founds Corduba", periodId="roman-150", date="c. 169–152 BCE", kind="construction",
         at=dict(landmarkId="roman-forum"), effect="construction",
         text="The Roman general Marcus Claudius Marcellus settled Romans and chosen natives at Corduba, beside an older Iberian town on the river, in the 160s or 150s BCE; the exact year is disputed. Strabo calls it the first colony the Romans sent to these parts. Augustus refounded it as Colonia Patricia and made it the capital of Baetica.",
         sourceIds=["wiki-marcellus", "ventura-corduba"]),
    dict(id="caesar-45bce", title="Caesar takes Corduba", periodId="roman-150", date="45 BCE", kind="riot",
         at=dict(latlon=(37.8846, -4.7810)), effect="fire",
         text="Corduba sided with Pompey's sons in the civil war. After his victory at Munda in March 45 BCE, Caesar stormed the town; the Bellum Hispaniense says 22,000 people were killed. The city recovered under Augustus, rebuilt with marble temples and a theatre.",
         sourceIds=["wiki-munda", "bellum-hispaniense"]),
    dict(id="seneca-born", title="Seneca is born in Corduba", periodId="roman-150", date="c. 4 BCE – 1 CE", kind="daily",
         at=dict(latlon=(37.8835, -4.7812)), effect="none",
         text="Lucius Annaeus Seneca, Stoic philosopher, tutor and minister of Nero, was born in Corduba into a wealthy equestrian family; his father Seneca the Elder was a writer on rhetoric and his nephew the poet Lucan was also born here. The family moved to Rome while he was a child. Where they lived is not known.",
         sourceIds=["wiki-seneca"]),
    dict(id="conquest-711", title="Mughith takes Córdoba", periodId="abd-al-rahman-800", date="October 711", kind="civic",
         at=dict(landmarkId="puerta-del-puente"), effect="crowd",
         text="After Tariq's victory over King Roderic, a detachment under Mughith al-Rumi rode on Córdoba. By the chroniclers' story a shepherd showed them a breach in the wall near the Bridge Gate on a night of rain and hail; the governor and his men held out in the church of St Acisclus for three months before they were taken.",
         sourceIds=["wiki-conquest-711", "kennedy-muslim-spain"]),
    dict(id="abd-al-rahman-756", title="Abd al-Rahman I becomes emir", periodId="abd-al-rahman-800", date="May 756", kind="ceremony",
         at=dict(landmarkId="umayyad-alcazar"), effect="procession",
         text="The last prince of the Umayyad family, escaped from the Abbasid massacre of 750 and five years of flight through North Africa, landed in al-Andalus in 755, defeated the governor Yusuf outside Córdoba and was proclaimed emir. He made the old governors' palace his own and planted a palm brought from Syria.",
         sourceIds=["wiki-abd-al-rahman-i", "kennedy-muslim-spain"]),
    dict(id="mosque-begun-786", title="The Great Mosque is begun", periodId="abd-al-rahman-800", date="785–786", kind="construction",
         at=dict(landmarkId="mezquita"), effect="construction",
         text="Abd al-Rahman I bought (by tradition) the church of St Vincent, which Muslims and Christians had shared, and built a mosque in about a year: eleven aisles of reused columns under double arches of red brick and white stone. His son Hisham I added the first minaret.",
         sourceIds=["wiki-mezquita", "nieto-mezquita"]),
    dict(id="revolt-arrabal-818", title="The Revolt of the Suburb", periodId="abd-al-rahman-800", date="March 818", kind="riot",
         at=dict(spotId="shaqunda-suq"), effect="fire",
         text="The people of Shaqunda, led by religious scholars and angered by taxes and the emir's foreign guard, marched on the Alcázar. Al-Hakam I's cavalry broke them; the suburb was burned, its leaders crucified and thousands of families exiled to Fez and Alexandria. The site was left empty for good.",
         sourceIds=["wiki-revuelta-arrabal", "kennedy-muslim-spain"]),
    dict(id="caliphate-929", title="Abd al-Rahman III takes the title of caliph", periodId="caliphal-950", date="January 929", kind="ceremony",
         at=dict(landmarkId="mezquita"), effect="crowd",
         text="Answering the Fatimids, who had proclaimed a caliphate in North Africa, the emir ordered that he be named Commander of the Faithful in the Friday sermon throughout al-Andalus. Córdoba became the capital of a caliphate, minting gold dinars and receiving embassies from Byzantium and the German emperor.",
         sourceIds=["wiki-abd-al-rahman-iii", "kennedy-muslim-spain"]),
    dict(id="madinat-al-zahra-936", title="Madinat al-Zahra is begun", periodId="caliphal-950", date="936 or 940", kind="construction",
         at=dict(latlon=(37.8860, -4.8030)), effect="construction",
         text="Seven kilometres west, on the foot of the sierra, the caliph began a palace city named for al-Zahra, 'the radiant'; the court moved there in the 940s. Chroniclers counted thousands of columns and workmen; the road west past the suburbs carried stone, officials and envoys every day. It was sacked in the Fitna after 1010.",
         sourceIds=["wiki-madinat-al-zahra", "acien-vallejo"]),
    dict(id="mihrab-mosaics", title="Mosaics for al-Hakam's mihrab", periodId="caliphal-950", date="961–971", kind="construction",
         at=dict(landmarkId="mezquita"), effect="construction",
         text="Al-Hakam II extended the mosque south by twelve bays and built a new mihrab and maqsura under ribbed domes. He asked the Byzantine emperor for a mosaicist; one came with tesserae of glass and gold and trained local craftsmen, who covered the mihrab's front with gold-ground inscriptions and vines.",
         sourceIds=["wiki-al-hakam-ii", "wiki-mezquita", "nieto-mezquita"]),
    dict(id="fitna-sack-1013", title="Berber troops sack Córdoba", periodId="caliphal-950", date="1009–1013", kind="riot",
         at=dict(landmarkId="umayyad-alcazar"), effect="fire",
         text="In 1009 a coup against Almanzor's son began the Fitna, a civil war of rival caliphs. Berber troops besieged the city, sacked Madinat al-Zahra and in May 1013 stormed Córdoba itself; the western suburbs were looted and abandoned. Ibn Hazm mourned his family's ruined house. The caliphate was abolished in 1031.",
         sourceIds=["wiki-fitna", "ibn-hazm", "kennedy-muslim-spain"]),
    dict(id="conquest-1236", title="Ferdinand III takes Córdoba", periodId="castilian-1300", date="29 June 1236", kind="ceremony",
         at=dict(landmarkId="mezquita"), effect="procession",
         text="After a siege that began with a surprise attack on the Axerquía in January, the city surrendered and its Muslims left. On the feast of Saints Peter and Paul a cross was raised on the minaret and the mosque was consecrated as the cathedral; by tradition the bells Almanzor had taken from Santiago were carried back by Muslim captives.",
         sourceIds=["wiki-siege-1236", "nieto-mezquita"]),
    dict(id="synagogue-1315", title="Isaac Moheb's synagogue", periodId="castilian-1300", date="1315", kind="construction",
         at=dict(landmarkId="synagogue"), effect="construction",
         text="A Hebrew inscription records that Isaac Moheb, son of Ephraim, built the synagogue in the year 5075 (1315), 'a lesser sanctuary'. Its plaster decoration was carved by Mudéjar craftsmen. Seventy-six years later, in 1391, mobs attacked the Judería of Córdoba as of Seville.",
         sourceIds=["wiki-synagogue", "escobar-camacho"]),
    dict(id="cathedral-nave-1523", title="A cathedral inside the mosque", periodId="habsburg-1600", date="1523; 1526", kind="construction",
         at=dict(landmarkId="mezquita"), effect="construction",
         text="Bishop Alonso Manrique began a Renaissance crossing and choir in the middle of the mosque in 1523, over the city council's protests; Hernán Ruiz I and his successors built it until 1607. Charles V, who had allowed it, is reported to have said on seeing it in 1526 that they had destroyed something unique to build something ordinary.",
         sourceIds=["wiki-mezquita", "nieto-mezquita"]),
]

